// Build a single extraction prompt from all received Truth docs, then hand it
// to Ollama. Input: $json = array of docs from load-docs.
// Output: { clientCode, prompt } single item.
var clientCode = 'SYNTH-ACME';
var docs = Array.isArray($json) ? $json : [$json];
var list = docs.map(function(d){
  return '- doc[' + (d.import_key || '') + '] type=' + (d.document_type || '') +
  ' title=' + (d.title || '') + ' uri=' + (d.source_uri || '') +
  ' checksum=' + (d.checksum || '');
}).join('\n');
var prompt =
  'You extract canonical facts from client-provided truth documents ' +
  '(mark as SYNTHETIC unless stated authentic).\n' +
  'Return STRICT JSON only, shape:\n' +
  '{"documents":[],' +
  '"entities":[{"entity_type","canonical_name","aliases":[]}],' +
  '"claims":[{"entity_name","field_key","claim_text","import_key"}]}\n' +
  'Every claim gets a deterministic import_key like "SYNTH-<dockey>-<n>".\n' +
  'Do NOT invent facts absent from the documents.\n\n' +
  'DOCUMENTS:\n' + (list || '(none)') + '\n\nJSON: ';
return { json: { clientCode: clientCode, prompt: prompt } };

// Parse the Ollama JSON response into import_truth_pack() inputs.
// Strictness: a non-JSON / empty reply yields empty arrays (fail closed, no
// fabricated facts); the DB import still validates and raises exceptions.
const raw = $json.response || '';
let data = {};
if (typeof raw === 'string') { try { data = JSON.parse(raw); } catch (e) { data = {}; } }
else if (raw && typeof raw === 'object') data = raw;
const docs = Array.isArray(data.documents) ? data.documents : [];

// Normalize entities: small models may echo the schema field names verbatim
// (e.g. entity_type='canonical_name') or put the real name in 'entity_name'.
// Fail closed: skip null / schema-copy artifacts.
const ents = Array.isArray(data.entities) ? data.entities : [];
const entities = [];
for (const e of ents) {
  if (!e || typeof e !== 'object' || e.claim) continue;
  const canonical = e.canonical_name || e.entity_name;
  if (!canonical) continue;
  const etype = (e.entity_type && e.entity_type !== 'canonical_name') ? e.entity_type : 'COMPANY';
  entities.push({
    entity_type: etype,
    canonical_name: canonical,
    aliases: Array.isArray(e.aliases) ? e.aliases : []
  });
}

const claims = Array.isArray(data.claims) ? data.claims : [];
return {
  json: {
    clientCode: 'SYNTH-ACME',
    pDocs: JSON.stringify(docs),
    pEntities: JSON.stringify(entities),
    pClaims: JSON.stringify(claims)
  }
};
